/// Official 4x3 national flag SVG for all 33 supported languages (lipis/flag-icons).
#[component]
pub fn LanguageFlagLogo(code: String, #[props(default = 22)] size: u32) -> Element {
    let h = ((size as f32) * 0.75).round() as u32;
    let svg_raw = match code.as_str() {
        "vi" => SVG_FLAG_VI,
        "en" => SVG_FLAG_EN,
        "zh-CN" => SVG_FLAG_ZH_CN,
        "zh-TW" => SVG_FLAG_ZH_TW,
        "ja" => SVG_FLAG_JA,
        "ko" => SVG_FLAG_KO,
        "th" => SVG_FLAG_TH,
        "id" => SVG_FLAG_ID,
        "ms" => SVG_FLAG_MS,
        "fil" => SVG_FLAG_FIL,
        "km" => SVG_FLAG_KM,
        "lo" => SVG_FLAG_LO,
        "hi" => SVG_FLAG_HI,
        "bn" => SVG_FLAG_BN,
        "ar" => SVG_FLAG_AR,
        "fa" => SVG_FLAG_FA,
        "he" => SVG_FLAG_HE,
        "ur" => SVG_FLAG_UR,
        "tr" => SVG_FLAG_TR,
        "ru" => SVG_FLAG_RU,
        "uk" => SVG_FLAG_UK,
        "pl" => SVG_FLAG_PL,
        "cs" => SVG_FLAG_CS,
        "de" => SVG_FLAG_DE,
        "fr" => SVG_FLAG_FR,
        "es" => SVG_FLAG_ES,
        "pt-BR" => SVG_FLAG_PT_BR,
        "it" => SVG_FLAG_IT,
        "nl" => SVG_FLAG_NL,
        "sv" => SVG_FLAG_SV,
        "ro" => SVG_FLAG_RO,
        "hu" => SVG_FLAG_HU,
        "el" => SVG_FLAG_EL,
        _ => SVG_FLAG_VI,
    };
    let html = render_svg(svg_raw, size, h);
    rsx! {
        span {
            class: "lang-flag-badge",
            "data-lang-flag": "{code}",
            "aria-hidden": "true",
            dangerous_inner_html: "{html}",
        }
    }
}
